import com.behsazan.corebanking.deposit.account.error.DepositAccountNotFoundException;
import com.behsazan.corebanking.deposit.account.waveb.domain.DepositAccountWaveBModels.*;
import com.behsazan.corebanking.deposit.account.waveb.oracle.DepositAccountWaveBRepository;
import com.behsazan.corebanking.deposit.account.waveb.oracle.DepositAccountWaveBRepository.*;
import org.springframework.stereotype.Service;
